def update_html_select_fixed(html, el_id, selected_val):
    pattern = re.compile(rf'(<select\b[^>]*\bid=["\']{re.escape(el_id)}["\'][^>]*>[\s\S]*?</select>)', re.IGNORECASE)
    def repl(m):
        block = m.group(1)
        # remove existing selected
        block = re.sub(r'\s*selected(=["\']?selected["\']?)?', '', block)
        # add selected to option with value=selected_val
        def opt_repl(om):
            otag = om.group(0)
            return otag[:-1] + ' selected="selected">'
        opt_pattern = re.compile(rf'<option\b[^>]*\bvalue=["\']{re.escape(selected_val)}["\'][^>]*>', re.IGNORECASE)
        return opt_pattern.sub(opt_repl, block)
    return pattern.sub(repl, html)

