def make_test_zip():
    js_zip_writer = """
function createZip(files) {
    // files: [{ name: 'test.txt', content: 'hello world' }]
    const textEncoder = new TextEncoder();

    // CRC32 table
    const crcTable = new Uint32Array(256);
    for (let i = 0; i < 256; i++) {
        let c = i;
        for (let k = 0; k < 8; k++) {
            c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
        }
        crcTable[i] = c >>> 0;
    }
    function crc32(buf) {
        let crc = 0xFFFFFFFF;
        for (let i = 0; i < buf.length; i++) {
            crc = (crc >>> 8) ^ crcTable[(crc ^ buf[i]) & 0xFF];
        }
        return (crc ^ 0xFFFFFFFF) >>> 0;
    }

    const localHeaders = [];
    const centralHeaders = [];
    let offset = 0;

    for (const f of files) {
        const nameBytes = textEncoder.encode(f.name);
        const dataBytes = typeof f.content === 'string' ? textEncoder.encode(f.content) : new Uint8Array(f.content);
        const crc = crc32(dataBytes);
        const size = dataBytes.length;

        // Local header (30 bytes + name)
        const lh = new Uint8Array(30 + nameBytes.length);
        const dv = new DataView(lh.buffer);
        dv.setUint32(0, 0x04034b50, true); // signature
        dv.setUint16(4, 20, true); // min version
        dv.setUint16(6, 0x0800, true); // flags: UTF-8
        dv.setUint16(8, 0, true); // compression: 0 (store)
        dv.setUint16(10, 0, true); // mod time
        dv.setUint16(12, 0, true); // mod date
        dv.setUint32(14, crc, true);
        dv.setUint32(18, size, true); // comp size
        dv.setUint32(22, size, true); // uncomp size
        dv.setUint16(26, nameBytes.length, true);
        dv.setUint16(28, 0, true); // extra len
        lh.set(nameBytes, 30);

        localHeaders.push(lh, dataBytes);

        // Central directory header (46 bytes + name)
        const ch = new Uint8Array(46 + nameBytes.length);
        const cdv = new DataView(ch.buffer);
        cdv.setUint32(0, 0x02014b50, true); // signature
        cdv.setUint16(4, 20, true); // version made by
        cdv.setUint16(6, 20, true); // version needed
        cdv.setUint16(8, 0x0800, true); // flags: UTF-8
        cdv.setUint16(10, 0, true); // compression: 0
        cdv.setUint16(12, 0, true);
        cdv.setUint16(14, 0, true);
        cdv.setUint32(16, crc, true);
        cdv.setUint32(20, size, true);
        cdv.setUint32(24, size, true);
        cdv.setUint16(28, nameBytes.length, true);
        cdv.setUint16(30, 0, true); // extra len
        cdv.setUint16(32, 0, true); // comment len
        cdv.setUint16(34, 0, true); // disk num
        cdv.setUint16(36, 0, true); // int attr
        cdv.setUint32(38, 0, true); // ext attr
        cdv.setUint32(42, offset, true); // local header offset
        ch.set(nameBytes, 46);

        centralHeaders.push(ch);
        offset += lh.length + dataBytes.length;
    }

    const cdOffset = offset;
    let cdSize = 0;
    for (const ch of centralHeaders) cdSize += ch.length;

    // End of central directory record (22 bytes)
    const eocd = new Uint8Array(22);
    const edv = new DataView(eocd.buffer);
    edv.setUint32(0, 0x06054b50, true);
    edv.setUint16(4, 0, true);
    edv.setUint16(6, 0, true);
    edv.setUint16(8, files.length, true);
    edv.setUint16(10, files.length, true);
    edv.setUint32(12, cdSize, true);
    edv.setUint32(16, cdOffset, true);
    edv.setUint16(20, 0, true);

    const allParts = [...localHeaders, ...centralHeaders, eocd];
    return new Blob(allParts, { type: 'application/zip' });
}
"""
